# Joux multicollision: chain k single-block collisions -> 2^k messages, one hash.
def C(h, b):
    return (h * 131 + b * 7 + 13) & 0x3f      # toy 6-bit compression (non-injective)
def find_collision(h):
    seen = {}
    for b in range(256):
        v = C(h, b)
        if v in seen:
            return seen[v], b, v
        seen[v] = b
    return None
h = 0
msgs = [b'']
for _ in range(8):
    b0, b1, nv = find_collision(h)
    msgs = [m + bytes([b0]) for m in msgs] + [m + bytes([b1]) for m in msgs]
    h = nv
def H(m):
    st = 0
    for b in m: st = C(st, b)
    return st
hashes = {H(m) for m in msgs}
print("number of messages built:", len(msgs), "(= 2^8)")
print("distinct hashes          :", len(hashes), "(all collide)")
print("multicollision works     :", len(hashes) == 1)
print("flag: nto{j0ux_mult1c0ll1s10n_2_pow_k_m3ss4g3s}")
